function permitidos():array{return [
'address-form'=>'escalafon_domicilio','academic-form'=>'escalafon_formacion_academica','training-form'=>'escalafon_capacitacion','production-form'=>'escalafon_produccion_intelectual','languages-form'=>'escalafon_idioma','displacement-form'=>'escalafon_desplazamiento','ascent-form'=>'escalafon_ascenso','pension-form'=>'escalafon_sistema_pensionario','cessations-form'=>'escalafon_cese','cts-form'=>'escalafon_cts','awards-form'=>'escalafon_premio_estimulo','trips-form'=>'escalafon_viaje_beca','sanctions-form'=>'escalafon_sancion_judicial','administrative-sanctions-form'=>'escalafon_sancion_administrativa','appeals-form'=>'escalafon_recurso_administrativo','leave-form'=>'escalafon_vacacion','unpaid-form'=>'escalafon_licencia_sin_goce','paid-form'=>'escalafon_licencia_con_goce','experience-form'=>'escalafon_experiencia_profesional','process-form'=>'escalafon_proceso','commissions-form'=>'escalafon_comision','nonworking-form'=>'escalafon_periodo_no_laborado','otherdocs-form'=>'escalafon_otro_documento','preventive-form'=>'escalafon_medida_preventiva','declaration-form'=>'escalafon_declaracion_jurada','modifier-form'=>'escalafon_modificatoria'];}
function tablaFormulario(string $form):string{$p=permitidos();if(!isset($p[$form]))salida(false,['mensaje'=>'Formulario no permitido.'],422);return $p[$form];}
function infraestructura(PDO $db,string $tabla):void{$db->exec("CREATE TABLE IF NOT EXISTS `{$tabla}` (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,dni VARCHAR(8) NOT NULL,codmod VARCHAR(30) NOT NULL,estado VARCHAR(40) NOT NULL DEFAULT 'APROBADO',documento_principal VARCHAR(255) NULL,documentos LONGTEXT NULL,origen_generico_id INT UNSIGNED NULL,creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_origen_generico (origen_generico_id),INDEX idx_persona (dni,codmod),INDEX idx_estado (estado)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db->exec("CREATE TABLE IF NOT EXISTS escalafon_formulario_campo (formulario VARCHAR(100) NOT NULL,etiqueta VARCHAR(255) NOT NULL,columna VARCHAR(64) NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(formulario,etiqueta),UNIQUE KEY uq_form_columna(formulario,columna)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");}
function nombreColumna(string $label):string{$ascii=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$label)?:$label;$slug=strtolower((string)preg_replace('/[^a-zA-Z0-9]+/','_',$ascii));$slug=trim($slug,'_')?:'campo';if(preg_match('/^[0-9]/',$slug))$slug='campo_'.$slug;return substr($slug,0,48);}
function mapa(PDO $db,string $form):array{$q=$db->prepare('SELECT etiqueta,columna FROM escalafon_formulario_campo WHERE formulario=:f');$q->execute(['f'=>$form]);$m=[];foreach($q->fetchAll() as $r)$m[(string)$r['etiqueta']]=(string)$r['columna'];return $m;}
function asegurarCampos(PDO $db,string $tabla,string $form,array $datos):array{$m=mapa($db,$form);foreach($datos as $label=>$_){$label=trim((string)$label);if($label===''||isset($m[$label]))continue;$base=nombreColumna($label);$col=$base;$i=0;while(in_array($col,$m,true)){$i++;$col=substr($base,0,40).'_'.substr(sha1($label.$i),0,7);}$db->exec("ALTER TABLE `{$tabla}` ADD COLUMN `{$col}` LONGTEXT NULL");$q=$db->prepare('INSERT INTO escalafon_formulario_campo(formulario,etiqueta,columna) VALUES(:f,:e,:c)');$q->execute(['f'=>$form,'e'=>$label,'c'=>$col]);$m[$label]=$col;}return $m;}
function insertar(PDO $db,string $tabla,string $form,string $dni,string $codmod,array $datos,array $docs,string $estado,?int $origen=null):int{$m=asegurarCampos($db,$tabla,$form,$datos);$cols=['dni','codmod','estado','documento_principal','documentos','origen_generico_id'];$vals=['dni'=>$dni,'codmod'=>$codmod,'estado'=>$estado,'documento_principal'=>$docs[0]??null,'documentos'=>$docs?json_encode($docs,JSON_UNESCAPED_SLASHES):null,'origen_generico_id'=>$origen];foreach($datos as $label=>$value){$col=$m[(string)$label];$cols[]=$col;$vals[$col]=is_scalar($value)||$value===null?(string)$value:json_encode($value,JSON_UNESCAPED_UNICODE);}$quoted=array_map(fn($c)=>"`{$c}`",$cols);$params=array_map(fn($c)=>":{$c}",$cols);$q=$db->prepare("INSERT INTO `{$tabla}` (".implode(',',$quoted).') VALUES('.implode(',',$params).')');$q->execute($vals);return(int)$db->lastInsertId();}
function migrar(PDO $db,string $tabla,string $form):void{if(!$db->query("SHOW TABLES LIKE 'escalafon_formulario_registro'")->fetchColumn())return;$q=$db->prepare("SELECT g.* FROM escalafon_formulario_registro g LEFT JOIN `{$tabla}` d ON d.origen_generico_id=g.id WHERE g.formulario=:f AND d.id IS NULL ORDER BY g.id");$q->execute(['f'=>$form]);foreach($q->fetchAll() as $r)insertar($db,$tabla,$form,(string)$r['dni'],(string)$r['codmod'],json_decode((string)$r['datos'],true)?:[],json_decode((string)($r['documentos']??''),true)?:[],(string)$r['estado'],(int)$r['id']);}

try{$db=obtenerConexion();$method=$_SERVER['REQUEST_METHOD']??'GET';$input=in_array($method,['DELETE','PATCH'],true)?(json_decode((string)file_get_contents('php://input'),true)?:[]):$_REQUEST;$form=trim((string)($input['formulario']??''));$tabla=tablaFormulario($form);infraestructura($db,$tabla);migrar($db,$tabla,$form);
if($method==='GET'){$dni=trim((string)($_GET['dni']??''));$codmod=trim((string)($_GET['codmod']??''));if(!preg_match('/^\d{8}$/',$dni))salida(false,['mensaje'=>'Consulta inválida.'],422);$m=mapa($db,$form);$q=$db->prepare("SELECT * FROM `{$tabla}` WHERE(dni=:dni OR codmod=:codmod)ORDER BY id DESC");$q->execute(['dni'=>$dni,'codmod'=>$codmod]);$rows=[];foreach($q->fetchAll() as $r){$datos=[];foreach($m as $label=>$col)if(isset($r[$col])&&$r[$col]!=='')$datos[$label]=$r[$col];$rows[]=['id'=>(int)$r['id'],'formulario'=>$form,'datos'=>$datos,'resumen'=>[],'documentos'=>json_decode((string)($r['documentos']??''),true)?:[],'estado'=>$r['estado'],'creado_en'=>$r['creado_en']];}salida(true,['registros'=>$rows,'tabla'=>$tabla]);}
if($method==='DELETE'){$id=(int)($input['id']??0);$dni=trim((string)($input['dni']??''));$q=$db->prepare("SELECT documentos,origen_generico_id FROM `{$tabla}` WHERE id=:id AND dni=:dni LIMIT 1");$q->execute(['id'=>$id,'dni'=>$dni]);$row=$q->fetch();if(!$row)salida(false,['mensaje'=>'Registro no encontrado.'],404);$db->prepare("DELETE FROM `{$tabla}` WHERE id=:id AND dni=:dni")->execute(['id'=>$id,'dni'=>$dni]);if(!empty($row['origen_generico_id'])&&$db->query("SHOW TABLES LIKE 'escalafon_formulario_registro'")->fetchColumn()){$db->prepare('DELETE FROM escalafon_formulario_registro WHERE id=:id AND dni=:dni')->execute(['id'=>(int)$row['origen_generico_id'],'dni'=>$dni]);}foreach(json_decode((string)($row['documentos']??''),true)?:[] as $ruta){$path=dirname(__DIR__).DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,(string)$ruta);if(is_file($path))@unlink($path);}salida(true);}
if($method==='PATCH'){$id=(int)($input['id']??0);$dni=trim((string)($input['dni']??''));$estado=strtoupper(trim((string)($input['estado']??'')));if(!in_array($estado,['APROBADO','DESAPROBADO','ANULADO','MODIFICADO'],true))salida(false,['mensaje'=>'Estado inválido.'],422);$datos=$input['datos']??[];if(!is_array($datos))$datos=[];$updates=['estado=:estado'];$params=['estado'=>$estado,'id'=>$id,'dni'=>$dni];if($datos){$m=asegurarCampos($db,$tabla,$form,$datos);foreach($datos as $label=>$value){$col=$m[(string)$label];$updates[]="`{$col}`=:{$col}";$params[$col]=is_scalar($value)||$value===null?(string)$value:json_encode($value,JSON_UNESCAPED_UNICODE);}}$q=$db->prepare("UPDATE `{$tabla}` SET ".implode(',',$updates)." WHERE id=:id AND dni=:dni");$q->execute($params);if(!$q->rowCount())salida(false,['mensaje'=>'Registro no encontrado o sin cambios.'],404);salida(true,['estado'=>$estado,'datos'=>$datos]);}
if($method!=='POST')salida(false,['mensaje'=>'Método no permitido.'],405);$dni=trim((string)($_POST['dni']??''));$codmod=trim((string)($_POST['codmod']??''));if(!preg_match('/^\d{8}$/',$dni)||$codmod==='')salida(false,['mensaje'=>'Identificación inválida.'],422);$datos=json_decode((string)($_POST['datos']??''),true);if(!is_array($datos)||!$datos)salida(false,['mensaje'=>'El formulario no contiene datos.'],422);$dir=dirname(__DIR__).'/uploads/formularios/'.$form;if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('No se pudo crear la carpeta.');$docs=[];foreach($_FILES as $file){if((int)($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;if((int)$file['error']!==UPLOAD_ERR_OK||(int)$file['size']>2097152)salida(false,['mensaje'=>'Cada archivo debe ser PDF y pesar máximo 2 MB.'],422);if((new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name'])!=='application/pdf')salida(false,['mensaje'=>'Solo se permiten PDF.'],422);$name=$dni.'-'.bin2hex(random_bytes(10)).'.pdf';if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('No se pudo guardar el documento.');$docs[]='uploads/formularios/'.$form.'/'.$name;}$id=insertar($db,$tabla,$form,$dni,$codmod,$datos,$docs,'APROBADO');salida(true,['id'=>$id,'tabla'=>$tabla,'mensaje'=>'Registro guardado correctamente en su tabla y campos correspondientes.']);
}catch(Throwable $e){if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();salida(false,['mensaje'=>'No se pudo completar la operación.','detalle'=>$e->getMessage()],500);}
